package uk.ac.ravensbourne.casevault.repository;
import static org.junit.jupiter.api.Assertions.*; import java.util.UUID; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest; import org.springframework.test.context.ActiveProfiles; import uk.ac.ravensbourne.casevault.domain.*;
@DataJpaTest @ActiveProfiles("test") class CaseRepositoryTest { @Autowired OrganisationRepository organisations; @Autowired UserAccountRepository users; @Autowired CaseRepository cases; @Test void tAuthz005TenantDerivedQueryDoesNotCrossOrganisation(){var first=organisations.save(new Organisation(UUID.randomUUID(),"First Org"));var second=organisations.save(new Organisation(UUID.randomUUID(),"Second Org"));var user=users.save(new UserAccount(UUID.randomUUID(),first,"first@example.test","hash",Role.CLIENT_USER));var record=cases.save(new CaseRecord(UUID.randomUUID(),first,"Synthetic incident","Synthetic description",Category.OTHER,Severity.LOW,user));assertTrue(cases.findByIdAndOrganisationId(record.getId(),first.getId()).isPresent());assertTrue(cases.findByIdAndOrganisationId(record.getId(),second.getId()).isEmpty());} }
